arguments.command:
for q in "badges" "location" "times" "correct" "setup" "booth setup" "convention" "anime expo" "hall 3" "hall 4"; do echo "=== $q ==="; curl -s -X POST https://slack.com/api/search.all -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d "{\"query\":\"$q\",\"count\":30}" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error'))
else:
    m=d.get('messages',{}); f=d.get('files',{})
    print('msg total:', m.get('total'), 'file total:', f.get('total'))
    for x in m.get('matches',[])[:10]:
        print(' ', x.get('user'), '|', x.get('channel',{}).get('name'), '|', x.get('ts'), '|', x.get('text','')[:110].replace(chr(10),' '))
    for x in f.get('matches',[])[:10]:
        print(' FILE:', x.get('name'), '|', x.get('permalink'))
"; done

